    List<LFVClassResultObjectBuilder>? CLASS_RESULTS,
    List<LFVClassResultObjectBuilder>? classResults,
    List<LFVFeatureSeparationObjectBuilder>? FEATURES,
    LFVWithinGroupObjectBuilder? WITHIN_GROUP,
    LFVWithinGroupObjectBuilder? withinGroup,
  })
      : _TEST_NAME = testName ?? TEST_NAME,
        _STATISTIC_NAME = statisticName ?? STATISTIC_NAME,
        _STATISTIC = STATISTIC,
        _P_VALUE = pValue ?? P_VALUE,
        _REAL_COUNT = realCount ?? REAL_COUNT,
        _DECOY_COUNT = decoyCount ?? DECOY_COUNT,
        _EXCLUDED_FEATURES = excludedFeatures ?? EXCLUDED_FEATURES,
        _RELATIVE = RELATIVE,
        _CLASSIFIER = CLASSIFIER,
        _AUC = AUC,
        _BALANCED_ACCURACY = balancedAccuracy ?? BALANCED_ACCURACY,
        _THRESHOLDS = THRESHOLDS,
        _RANK_PROBABILITIES = rankProbabilities ?? RANK_PROBABILITIES,
        _CLASS_RESULTS = classResults ?? CLASS_RESULTS,
        _FEATURES = FEATURES,
        _WITHIN_GROUP = withinGroup ?? WITHIN_GROUP;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? TEST_NAMEOffset = _TEST_NAME == null ? null
        : fbBuilder.writeString(_TEST_NAME!);
    final int? STATISTIC_NAMEOffset = _STATISTIC_NAME == null ? null
        : fbBuilder.writeString(_STATISTIC_NAME!);
    final int? EXCLUDED_FEATURESOffset = _EXCLUDED_FEATURES == null ? null
        : fbBuilder.writeList(_EXCLUDED_FEATURES!.map(fbBuilder.writeString).toList());
    final int? CLASSIFIEROffset = _CLASSIFIER?.getOrCreateOffset(fbBuilder);
    final int? THRESHOLDSOffset = _THRESHOLDS == null ? null
        : fbBuilder.writeList(_THRESHOLDS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? RANK_PROBABILITIESOffset = _RANK_PROBABILITIES == null ? null
        : fbBuilder.writeList(_RANK_PROBABILITIES!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? CLASS_RESULTSOffset = _CLASS_RESULTS == null ? null
        : fbBuilder.writeList(_CLASS_RESULTS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? FEATURESOffset = _FEATURES == null ? null
        : fbBuilder.writeList(_FEATURES!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? WITHIN_GROUPOffset = _WITHIN_GROUP?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(16);
    fbBuilder.addOffset(0, TEST_NAMEOffset);
    fbBuilder.addOffset(1, STATISTIC_NAMEOffset);
    fbBuilder.addFloat64(2, _STATISTIC);
    fbBuilder.addFloat64(3, _P_VALUE);
    fbBuilder.addUint32(4, _REAL_COUNT);
    fbBuilder.addUint32(5, _DECOY_COUNT);
    fbBuilder.addOffset(6, EXCLUDED_FEATURESOffset);
    fbBuilder.addBool(7, _RELATIVE);
    fbBuilder.addOffset(8, CLASSIFIEROffset);
    fbBuilder.addFloat64(9, _AUC);
    fbBuilder.addFloat64(10, _BALANCED_ACCURACY);
    fbBuilder.addOffset(11, THRESHOLDSOffset);
    fbBuilder.addOffset(12, RANK_PROBABILITIESOffset);
    fbBuilder.addOffset(13, CLASS_RESULTSOffset);
    fbBuilder.addOffset(14, FEATURESOffset);
    fbBuilder.addOffset(15, WITHIN_GROUPOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
///  Labelled Feature Vectors - labelled rows and, optionally, the report of a
///  test that distinguishes their classes.
class LFV {
  LFV._(this._bc, this._bcOffset);
  factory LFV(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<LFV> reader = _LFVReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Name of the feature set or view, e.g. "gp" (from element sets), "ffm"
  ///  (from propagated ephemeris).
  String? get VIEW => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  ///  Feature names, in the order of every row's VALUES.
  List<String>? get FEATURE_NAMES => const fb.ListReader<String>(fb.StringReader()).vTableGetNullable(_bc, _bcOffset, 6);
  List<String>? get featureNames => FEATURE_NAMES;
  ///  Unit of each feature, same order, e.g. "km", "deg", "km/day", "1";
  ///  empty = not stated.
  List<String>? get FEATURE_UNITS => const fb.ListReader<String>(fb.StringReader()).vTableGetNullable(_bc, _bcOffset, 8);
  List<String>? get featureUnits => FEATURE_UNITS;
  ///  Window of data the features were computed over, Unix milliseconds
  ///  [start, end); 0 = not stated.
  int get WINDOW_START_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 10, 0);
  int get windowStartMs => WINDOW_START_MS;
  int get WINDOW_END_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 12, 0);
  int get windowEndMs => WINDOW_END_MS;
  ///  Fewest data points a source needed to get a row.
  int get MIN_POINTS => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 14, 0);
  int get minPoints => MIN_POINTS;
  List<LFVRow>? get ROWS => const fb.ListReader<LFVRow>(LFVRow.reader).vTableGetNullable(_bc, _bcOffset, 16);
  ///  Sources offered, reference objects compared against (the catalog),
  ///  and sources skipped for having too few points.
  int get SOURCE_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 18, 0);
  int get sourceCount => SOURCE_COUNT;
  int get REFERENCE_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 20, 0);
  int get referenceCount => REFERENCE_COUNT;
  int get SKIPPED_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 22, 0);
  int get skippedCount => SKIPPED_COUNT;
  ///  Unix milliseconds this record was generated; 0 = not stated.
  int get GENERATED_AT_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 24, 0);
  int get generatedAtMs => GENERATED_AT_MS;
  LFVTestReport? get REPORT => LFVTestReport.reader.vTableGetNullable(_bc, _bcOffset, 26);

  @override
  String toString() {
    return 'LFV{VIEW: ${VIEW}, featureNames: ${featureNames}, featureUnits: ${featureUnits}, windowStartMs: ${windowStartMs}, windowEndMs: ${windowEndMs}, minPoints: ${minPoints}, ROWS: ${ROWS}, sourceCount: ${sourceCount}, referenceCount: ${referenceCount}, skippedCount: ${skippedCount}, generatedAtMs: ${generatedAtMs}, REPORT: ${REPORT}}';
  }
}

class _LFVReader extends fb.TableReader<LFV> {
  const _LFVReader();

  @override
  LFV createObject(fb.BufferContext bc, int offset) =>
    LFV._(bc, offset);
}

class LFVBuilder {
  LFVBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(12);
  }

  int addViewOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addFeatureNamesOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addFeatureUnitsOffset(int? offset) {
    fbBuilder.addOffset(2, offset);
    return fbBuilder.offset;
  }
  int addWindowStartMs(int? WINDOW_START_MS) {
    fbBuilder.addInt64(3, WINDOW_START_MS);
    return fbBuilder.offset;
  }
  int addWindowEndMs(int? WINDOW_END_MS) {
    fbBuilder.addInt64(4, WINDOW_END_MS);
    return fbBuilder.offset;
  }
  int addMinPoints(int? MIN_POINTS) {
    fbBuilder.addUint32(5, MIN_POINTS);
    return fbBuilder.offset;
  }
  int addRowsOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addSourceCount(int? SOURCE_COUNT) {
    fbBuilder.addUint32(7, SOURCE_COUNT);
    return fbBuilder.offset;
  }
  int addReferenceCount(int? REFERENCE_COUNT) {
    fbBuilder.addUint32(8, REFERENCE_COUNT);
    return fbBuilder.offset;
  }
  int addSkippedCount(int? SKIPPED_COUNT) {
    fbBuilder.addUint32(9, SKIPPED_COUNT);
    return fbBuilder.offset;
  }
  int addGeneratedAtMs(int? GENERATED_AT_MS) {
    fbBuilder.addInt64(10, GENERATED_AT_MS);
    return fbBuilder.offset;
  }
  int addReportOffset(int? offset) {
    fbBuilder.addOffset(11, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

